import type { Schema } from '../../../schema';
import { archive_tribe_log } from './tribeLog';

type Squad = Schema['探索编队'][string];

const OUTBOUND_STATUSES = new Set<Squad['状态']>(['探索中', '采集中', '狩猎中']);

function action_from_status(status: Squad['状态']): '探索' | '狩猎' | '采集' {
  if (status === '狩猎中') return '狩猎';
  if (status === '采集中') return '采集';
  return '探索';
}

function mark_squad_members_returned(stat: Schema, squad: Squad): void {
  for (const name of squad.具名成员) {
    const npc = stat.具名NPC[name];
    if (!npc) continue;
    npc.当前任务 = '归来清点';
    npc.当前位置 = '营地';
    if (npc.状态 === '外出') {
      npc.状态 = '疲惫';
    }
  }
}

/** 创建「归来清点·{队名}」待办，供 EJS 注入结算规则、AI 输出 settlement_card */
export function ensure_squad_return_pending_affair(stat: Schema, squad_name: string, squad: Squad): void {
  const action = action_from_status(squad.状态);
  const settlement_name = `归来清点·${squad_name}`;
  if (!stat.综合事物[settlement_name]) {
    stat.综合事物[settlement_name] = {
      说明: `自「${squad.目标区域 || '未知区域'}」归来，计划 ${squad.计划时长}h 已到，待清点战利品与伤亡`,
      状态: '进行中',
      来源: '时间结算',
      创建日期: stat.世界.兽历,
      具名参与: [...squad.具名成员],
      元数据: {
        类型: '探索结算',
        编队: squad_name,
        行动: action,
        目标区域: squad.目标区域,
        计划时长: squad.计划时长,
      },
    };
  }

  archive_tribe_log(stat, {
    类型: '探索',
    关联键: `${squad_name}·归来`,
    说明: `${squad_name} 自 ${squad.目标区域} ${action}归来，待清点`,
    归档摘要: `${stat.世界.兽历} ${stat.世界.时间}：${squad_name} 自「${squad.目标区域}」${action}归来（待清点）`,
    创建日期: squad.出发于?.兽历 ?? stat.世界.兽历,
    具名参与: [...squad.具名成员],
  });
}

function return_squad_from_mission(stat: Schema, squad_name: string, squad: Squad): void {
  ensure_squad_return_pending_affair(stat, squad_name, squad);
  squad.状态 = '待命';
  squad.已耗工时 = 0;
  delete squad.出发于;
  mark_squad_members_returned(stat, squad);
  console.info('[探索编队] 计划时长已到，已归营:', squad_name);
}

/** 外出编队随游戏时间累计工时，到期归营并创建待剧情结算 */
export function sync_exploration_squads_time(data: Schema, hours: number): boolean {
  if (hours <= 0) {
    return false;
  }
  let changed = false;
  for (const name of Object.keys(data.探索编队)) {
    const squad = data.探索编队[name];
    if (!squad || !OUTBOUND_STATUSES.has(squad.状态)) {
      continue;
    }
    squad.已耗工时 = (squad.已耗工时 ?? 0) + hours;
    changed = true;
    if (squad.已耗工时 >= squad.计划时长) {
      return_squad_from_mission(data, name, squad);
    }
  }
  return changed;
}
